from collections import deque

def comps(grid):
 h,w=grid.shape; seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   v=int(grid[r,c])
   if v==int(grid[0,0]) or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    x,y=q.pop(); pts.append((x,y))
    for dx in (-1,0,1):
     for dy in (-1,0,1):
      nx,ny=x+dx,y+dy
      if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and int(grid[nx,ny])==v:
       seen.add((nx,ny));q.append((nx,ny))
   out.append((v,pts))
 return out

def normalize(pts):
 mr=min(r for r,c in pts); mc=min(c for r,c in pts)
 return frozenset((r-mr,c-mc) for r,c in pts)
